```latex
\documentclass[aps,prd,reprint,superscriptaddress,nofootinbib]{revtex4-2}
\usepackage{amsmath}
\usepackage{amssymb}
\usepackage{hepparticles}
\usepackage{siunitx}

\begin{document}

\title{Measurement of the $e^+ e^- \to K^+ K^- \pi^+ \pi^-$, $K^+ K^- \pi^0 \pi^0$, and $K^+ K^- K^+ K^-$ Cross Sections Using Initial-State Radiation at BaBar}

\author{The BaBar Collaboration}

\date{\today}

\begin{abstract}
We present measurements of the cross sections for the hadronic processes $e^+ e^- \to K^+ K^- \pi^+ \pi^-$, $K^+ K^- \pi^0 \pi^0$, and $K^+ K^- K^+ K^-$ as a function of center-of-mass energy from threshold up to $5.0\,\text{GeV}$. The data set analyzed corresponds to an integrated luminosity of $232\,\text{fb}^{-1}$ collected at and near the $\Upsilon(4S)$ resonance with the BaBar detector at the PEP-II $e^+ e^-$ asymmetric-energy collider. The cross sections are extracted using the initial-state radiation (ISR) technique by measuring the $e^+ e^- \to K^+ K^- \pi^+ \pi^- \gamma$, $K^+ K^- \pi^0 \pi^0 \gamma$, and $K^+ K^- K^+ K^- \gamma$ final states, where $\gamma$ represents the energetic ISR photon. We perform a detailed study of the intermediate resonant structures contributing to these modes. In particular, we observe prominent contributions from $K^*(890)^0 \bar{K}^*(890)^0$, $K^*(890) K \pi$, $\phi(1020) \pi \pi$, and $f_1(1285)$ intermediate states. In the $\phi(1020) f_0(980)$ submode, a distinct resonant structure near $2.12\,\text{GeV}/c^2$ is observed, consistent with the $\phi(2170)$ vector state. Systematic uncertainties are rigorously evaluated for both the total cross sections and submode branching fractions. These results provide improved inputs for calculations of the hadronic vacuum polarization contribution to the anomalous magnetic moment of the muon, $(g-2)_\mu$, and offer critical insights into light-meson spectroscopy.
\end{abstract}

